-- V595: find-battery-peak says "Return the index of any peak. If several exist, any one works.",
-- but its Drivers printed the returned index and the Grader compared it with one stored index, so a
-- case with two peaks would reject a correct answer (#354). All 10 cases had exactly one peak, so no
-- past Verdict was wrong; past Verdicts stand (docs/adr/0010).
--
-- The four Drivers now check the returned index (in range, and greater than each neighbour that
-- exists, the ends counting as beside -infinity) and print VALID, or INVALID:<index> otherwise, as
-- order-group-tasks' and space-cookie-bakes' do. So:
--   1. every Test Case expects VALID;
--   2. seven hidden cases are added, six with several peaks (one with peaks at both ends only);
--   3. the statement, English and Korean, says the judge checks the answer, in order-group-tasks'
--      sentence (V583). Examples still show a returned index.
-- FindBatteryPeakGuarantee checks every case's input against the constraints and that VALID is
-- its only accepted output.

UPDATE test_cases SET expected_output = 'VALID'
WHERE problem_id = (SELECT id FROM problems WHERE slug = 'find-battery-peak');

INSERT INTO test_cases (problem_id, input, expected_output, is_sample, order_index)
